    data_rows = []
    for i, row in enumerate(rows):
        ths = row.find_all('th')
        tds = row.find_all('td')
        if ths and i == 0:
            headers = [th.get_text(strip=True) for th in ths]
        elif tds:
            data_rows.append([td.get_text(strip=True) for td in tds])
    if headers:
        df = pd.DataFrame(data_rows, columns=headers)
    else:
        df = pd.DataFrame(data_rows)
    return df

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("webpage_url must be a non-empty string.")
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table_element = tree.xpath('//table')
        if not table_element:
            return 0
        tables = pd.read_html(response.content)
        if not tables:
            return 0
        df = tables[0]
        if df.empty:
            return 0
        try:
            conn = sqlite3.connect(database_name)
            df.to_sql('my_table', conn, if_exists='replace', index=False)
            row_count = len(df)
            conn.commit()
            conn.close()
        except sqlite3.DatabaseError as e:
            raise sqlite3.DatabaseError(f"Database error: {e}")
        return row_count
    except Exception as e:
        raise ValueError(f"Error parsing HTML content: {e}")

